namespace sv_80a4eb9786c34e179068f5910514f173.Services;

/// <summary>
/// Scoped service (per-circuit) that holds the current warehouse selection
/// and notifies subscribers when it changes.
/// </summary>
public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } = new List<(string, string)>
    {
        ("WH-001", "Warehouse A — Downtown"),
        ("WH-002", "Warehouse B — Airport"),
        ("WH-003", "Warehouse C — Dockside"),
        ("WH-004", "Warehouse D — Suburban")
    };
}

namespace sv_80a4eb9786c34e179068f5910514f173.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts and notifies all
/// subscribed components when new data arrives.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private Timer? _pollingTimer;
    private int _subscriberCount;
    private int _lastAlertCount;

    public int CurrentAlertCount => _lastAlertCount;

    /// <summary>
    /// Fired when polling retrieves new alert data. All subscribed components
    /// should re-render when this fires.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query for items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate variable latency and random count
        int count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Components call this when they become visible and want polling to run.
    /// Polling starts on the first subscriber and stops when all unsubscribe.
    /// </summary>
    public void Subscribe()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            StartPolling();
        }
    }

    /// <summary>
    /// Components call this when they are disposed or leave the page.
    /// </summary>
    public void Unsubscribe()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            StopPolling();
        }
    }

    private void StartPolling()
    {
        _pollingTimer?.Dispose();
        // Poll immediately, then every 10 seconds
        _pollingTimer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
    }

    private void StopPolling()
    {
        _pollingTimer?.Dispose();
        _pollingTimer = null;
    }

    private async void PollCallback(object? state)
    {
        var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        _lastAlertCount = count;

        if (OnAlertCountChanged is not null)
        {
            await OnAlertCountChanged.Invoke();
        }
    }

    private async void HandleWarehouseChanged()
    {
        // When warehouse changes, immediately refresh alert data
        if (_subscriberCount > 0)
        {
            var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
            _lastAlertCount = count;

            if (OnAlertCountChanged is not null)
            {
                await OnAlertCountChanged.Invoke();
            }
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChanged;
        StopPolling();
    }
}

