@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label for="warehouse-select" class="form-label mb-0 me-2 text-white">Warehouse:</label>
    <select id="warehouse-select" class="form-select form-select-sm" style="width: auto; display: inline-block;"
            value="@WarehouseState.CurrentWarehouseId" @onchange="OnWarehouseChanged">
        @foreach (var wh in Services.WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
        }
    }

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@inject Services.InventoryAlertService AlertService
@implements IDisposable

<span class="alert-badge position-relative">
    <span class="bi bi-exclamation-triangle-fill-nav-menu" aria-hidden="true"></span>
    @if (AlertService.CurrentAlertCount > 0)
    {
        <span class="badge bg-danger rounded-pill">@AlertService.CurrentAlertCount</span>
    }
    else
    {
        <span class="badge bg-success rounded-pill">0</span>
    }
</span>

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += HandleAlertUpdate;
        // Subscribe so polling is active when this badge is rendered
        AlertService.Subscribe();
    }

    private async Task HandleAlertUpdate()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= HandleAlertUpdate;
        AlertService.Unsubscribe();
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-header">
        <strong>Current Warehouse:</strong> @GetWarehouseName()
    </div>
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            Items below minimum levels:
            <span class="badge @(AlertService.CurrentAlertCount > 0 ? "bg-danger" : "bg-success") fs-5">
                @AlertService.CurrentAlertCount
            </span>
        </p>
        <p class="text-muted">
            <small>Polling every 10 seconds. Last update: @_lastUpdate.ToString("HH:mm:ss")</small>
        </p>
    </div>
</div>

<div class="card">
    <div class="card-header">How This Works</div>
    <div class="card-body">
        <ul>
            <li><strong>Scoped services</strong> — each circuit (user session) gets its own instance of
                <code>WarehouseStateService</code> and <code>InventoryAlertService</code>.</li>
            <li><strong>Event-driven updates</strong> — components subscribe to service events; when data changes,
                all subscribers re-render automatically.</li>
            <li><strong>Polling lifecycle</strong> — polling starts when this dashboard is visible and stops when
                you navigate away.</li>
            <li>Change the warehouse in the top bar — this page and the sidebar badge update immediately.</li>
        </ul>
    </div>
</div>

@code {
    private DateTime _lastUpdate = DateTime.Now;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChange;
        AlertService.OnAlertCountChanged += HandleAlertUpdate;
        AlertService.Subscribe();
    }

    private void HandleStateChange()
    {
        InvokeAsync(StateHasChanged);
    }

    private async Task HandleAlertUpdate()
    {
        _lastUpdate = DateTime.Now;
        await InvokeAsync(StateHasChanged);
    }

    private string GetWarehouseName()
    {
        var wh = Services.WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId);
        return wh == default ? WarehouseState.CurrentWarehouseId : wh.Name;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChange;
        AlertService.OnAlertCountChanged -= HandleAlertUpdate;
        AlertService.Unsubscribe();
    }
}

